43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.PetDto;
45	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.samples.petclinic.util.Households;
50	import org.springframework.samples.petclinic.util.Localities;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /**
69	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
70	     * new owner's id, its assigned {@code customerCode}, its {@code registrationDate} and its
71	     * numeric {@code membershipLevel}.
72	     */
73	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    public OwnerRestControllerV1(ClinicService clinicService,
84	                                 OwnerMapper ownerMapper,
85	                                 PetMapper petMapper,
86	                                 VisitMapper visitMapper) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
96	        Collection<Owner> owners;
97	        if (lastName != null) {
98	            owners = this.clinicService.findOwnerByLastName(lastName);
99	        } else {
100	            owners = this.clinicService.findAllOwners();
101	        }
102	        if (owners.isEmpty()) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        applyAddress(owner, ownerFieldsDto);
124	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
125	        rejectFutureRegistrationDate(registrationDate);
126	        if (registrationDate == null) {
127	            registrationDate = java.time.LocalDate.now();
128	        }
129	        registrationDate = toBusinessDay(registrationDate);
130	        owner.setRegistrationDate(registrationDate);
131	        rejectDailyLimitReached(registrationDate);
132	        rejectCityAtCapacity(owner.getCity());
133	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
134	        owner.setTelephone(telephone);
135	        String email = normalizeEmail(ownerFieldsDto.getEmail());
136	        owner.setEmail(email);
137	        owner.setPostcode(validatePostcode(owner.getCity(), ownerFieldsDto.getPostcode()));
138	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
139	        rejectDuplicateIdentity(owner);
140	        rejectDuplicateHousehold(owner, sharesHousehold);
141	        String region = Localities.region(owner.getPostcode(), owner.getCity());
142	        owner.setCustomerCode(assignCustomerCode(region, owner.getTelephone(), owner.getLastName()));
143	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
144	        owner.setBulkSignupWarning(computeBulkSignupWarning(registrationDate));
145	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getPostcode()) + 1);
146	        // A declared household member (sharesHousehold) is created but is not a suspected duplicate.
147	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(owner);
148	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
149	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
150	        this.clinicService.saveOwner(owner);
151	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
152	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
153	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
154	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
155	        headers.setLocation(UriComponentsBuilder.newInstance()
156	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
157	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
158	    }
159	
160	    /**
161	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server
162	     * date (in the future). Only an explicitly supplied date is validated; a {@code null} date
163	     * (which later defaults to the server date) is accepted. The check is against the raw supplied
164	     * date, before any business-day adjustment.
165	     *
166	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
167	     * @throws FutureRegistrationDateException (400 Bad Request) if the supplied date is in the future
168	     */
169	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
170	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
171	            throw new FutureRegistrationDateException(registrationDate);
172	        }
173	    }
174	
175	    /**
176	     * The maximum number of owners that may be created in a single day. Creating an owner once this
177	     * many owners already carry today's {@code registrationDate} is rejected.
178	     */
179	    private static final int DAILY_OWNER_LIMIT = 100;
180	
181	    /**
182	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
183	     * given business day as their {@code registrationDate}. The count is keyed by the
184	     * business-day-adjusted registration date of the owner being created (see
185	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
186	     * with no {@code registrationDate} are ignored.
187	     *
188	     * @param registrationDate the business-day-adjusted registration date of the owner being created
189	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
190	     */
191	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
192	        long count = this.clinicService.findAllOwners().stream()
193	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
194	            .count();
195	        if (count >= DAILY_OWNER_LIMIT) {
196	            throw new DailyOwnerLimitException(registrationDate);
197	        }
198	    }
199	
200	    /**
201	     * The threshold of owners already created on a business day beyond which a bulk-signup warning is
202	     * raised on a new owner. Once strictly more than this many owners already carry the day as their
203	     * {@code registrationDate}, the new owner's {@code bulkSignupWarning} is set to {@code true}.
204	     */
205	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
206	
207	    /**
208	     * Computes the {@code bulkSignupWarning} for an owner being created: {@code true} when more than
209	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created today, otherwise
210	     * {@code false}. Existing owners are counted the same way the daily-limit rule counts them (see
211	     * {@link #rejectDailyLimitReached}), keyed by the business-day-adjusted registration date, and the
212	     * owner being created is excluded (it has not yet been saved).
213	     *
214	     * @param registrationDate the business-day-adjusted registration date of the owner being created
215	     * @return {@code true} if more than the threshold of owners already carry this business day
216	     */
217	    private boolean computeBulkSignupWarning(java.time.LocalDate registrationDate) {
218	        long count = this.clinicService.findAllOwners().stream()
219	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
220	            .count();
221	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
222	    }
223	
224	    /**
225	     * The fixed public holidays the business-day roll skips. A registration date landing on any of
226	     * these dates is rolled forward, just as it is for a weekend.
227	     */
228	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
229	        java.time.LocalDate.parse("2026-01-01"),
230	        java.time.LocalDate.parse("2026-01-26"),
231	        java.time.LocalDate.parse("2026-04-25"),
232	        java.time.LocalDate.parse("2026-12-25"),
233	        java.time.LocalDate.parse("2026-12-28"));
234	
235	    /**
236	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
237	     * holiday is moved forward to the next non-holiday weekday; an ordinary weekday is returned
238	     * unchanged. This applies to the effective registration date whether it was supplied in the
239	     * request or defaulted to the server date, and every value derived from the registration date
240	     * uses the adjusted result.
241	     *
242	     * @param date the effective registration date
243	     * @return {@code date} itself when it is a non-holiday weekday, otherwise the next business day
244	     */
245	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
246	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
247	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
248	            || PUBLIC_HOLIDAYS.contains(date)) {
249	            date = date.plusDays(1);
250	        }
251	        return date;
252	    }
253	
254	    /**
255	     * The maximum number of owners a single city may contain. Creating an owner in a city that
256	     * already holds this many owners is rejected.
257	     */
258	    private static final int CITY_CAPACITY = 50;
259	
260	    /**
261	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
262	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
263	     * treated as empty).
264	     *
265	     * @param city the city of the owner being created
266	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
267	     */
268	    private void rejectCityAtCapacity(String city) {
269	        String cityValue = city == null ? "" : city;
270	        long count = this.clinicService.findAllOwners().stream()
271	            .filter(existing -> cityValue.equalsIgnoreCase(
272	                existing.getCity() == null ? "" : existing.getCity()))
273	            .count();
274	        if (count >= CITY_CAPACITY) {
275	            throw new CityAtCapacityException(city);
276	        }
277	    }
278	
279	    /**
280	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
281	     * REGION is the owner's canonical region (derived by preferring the postcode, see
282	     * {@link Localities#region(String, String)} — the same region derivation shared with the
283	     * {@code locality}) and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of
284	     * the normalized (E.164) telephone concatenated with the last name (e.g. {@code 'NSW-3A7F9C2E'}).
285	     * The code is derived from the owner's own identity fields; it carries no sequence number.
286	     * <p>
287	     * When the computed code collides with an existing owner's {@code customerCode}, it is
288	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
289	     * it unique (e.g. {@code 'NSW-3A7F9C2E-2'}), and the de-duplicated code is returned.
290	     *
291	     * @param region the owner's canonical region (the identity's REGION, shared with the locality)
292	     * @param telephone the owner's normalized (E.164) telephone
293	     * @param lastName the owner's last name
294	     * @return the assigned customer code, de-duplicated to be unique among existing owners
295	     */
296	    private String assignCustomerCode(String region, String telephone, String lastName) {
297	        String basis = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
298	        String hash8 = sha256UpperHex(basis).substring(0, 8);
299	        String code = region + "-" + hash8;
300	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
301	            .map(Owner::getCustomerCode)
302	            .filter(java.util.Objects::nonNull)
303	            .collect(java.util.stream.Collectors.toSet());
304	        if (!existing.contains(code)) {
305	            return code;
306	        }
307	        for (int n = 2; ; n++) {
308	            String candidate = code + "-" + n;
309	            if (!existing.contains(candidate)) {
310	                return candidate;
311	            }
312	        }
313	    }
314	
315	    /**
316	     * Returns the full upper-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
317	     */
318	    private static String sha256UpperHex(String value) {
319	        try {
320	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
321	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
322	            StringBuilder sb = new StringBuilder(digest.length * 2);
323	            for (byte b : digest) {
324	                sb.append(String.format("%02X", b));
325	            }
326	            return sb.toString();
327	        }
328	        catch (java.security.NoSuchAlgorithmException e) {
329	            throw new IllegalStateException("SHA-256 not available", e);
330	        }
331	    }
332	
333	    /**
334	     * Counts how many existing owners share the given first and last name, compared
335	     * case-insensitively, at the time this owner is created. The value excludes the owner
336	     * being created (which has not yet been saved) and is stored on the new owner and returned
337	     * as its {@code namesakeCount}.
338	     *
339	     * @param firstName the first name of the owner being created
340	     * @param lastName the last name of the owner being created
341	     * @return the number of existing owners with the same first and last name
342	     */
343	    private int countNamesakes(String firstName, String lastName) {
344	        String first = firstName == null ? "" : firstName;
345	        String last = lastName == null ? "" : lastName;
346	        return (int) this.clinicService.findAllOwners().stream()
347	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
348	                && last.equalsIgnoreCase(existing.getLastName()))
349	            .count();
350	    }
351	
352	    /**
353	     * Counts how many existing owners belong to the same household as the owner being created, i.e.
354	     * share its {@code householdId} (derived by {@link Households#householdId} from the normalized last
355	     * name and postcode). The value excludes the owner being created (which has not yet been saved), so
356	     * the household's size after this create is this count plus one. It is stored on the new owner.
357	     *
358	     * @param lastName the last name of the owner being created
359	     * @param postcode the postcode of the owner being created
360	     * @return the number of existing owners sharing this owner's household
361	     */
362	    private int countHouseholdMembers(String lastName, String postcode) {
363	        String householdId = Households.householdId(lastName, postcode);
364	        return (int) this.clinicService.findAllOwners().stream()
365	            .filter(existing -> householdId.equals(
366	                Households.householdId(existing.getLastName(), existing.getPostcode())))
367	            .count();
368	    }
369	
370	    /**
371	     * Rejects creating an owner that would join an existing household without opting in. The household
372	     * is keyed on the computed {@code householdId} (see {@link Households#householdId}, derived from the
373	     * normalized last name and postcode), so an owner sharing an existing owner's last name and postcode
374	     * is the same household. When another owner already belongs to that household the create is rejected,
375	     * unless the request opts in with {@code sharesHousehold}, which bypasses this block and creates the
376	     * owner as a declared household member. An owner with no postcode is never treated as a household
377	     * duplicate.
378	     *
379	     * @param owner the owner being created, with its last name and postcode already set
380	     * @param sharesHousehold whether the request opted in via {@code sharesHousehold}
381	     * @throws DuplicateHouseholdException (409 Conflict) if the owner joins an existing household and did
382	     *         not opt in
383	     */
384	    private void rejectDuplicateHousehold(Owner owner, boolean sharesHousehold) {
385	        if (sharesHousehold) {
386	            return;
387	        }
388	        String postcode = owner.getPostcode();
389	        if (postcode == null) {
390	            return;
391	        }
392	        String householdId = Households.householdId(owner.getLastName(), postcode);
393	        boolean exists = this.clinicService.findAllOwners().stream()
394	            .filter(this::isNotDeleted)
395	            .anyMatch(existing -> householdId.equals(
396	                Households.householdId(existing.getLastName(), existing.getPostcode())));
397	        if (exists) {
398	            throw new DuplicateHouseholdException(owner.getLastName(), postcode);
399	        }
400	    }
401	
402	    /**
403	     * Finds the existing owner, if any, that the owner being created is a soft duplicate of: an owner
404	     * sharing this owner's last name (compared case-insensitively) and postcode (an exact match of the
405	     * stored 4-digit value) while carrying a <em>different</em> telephone. A soft match is distinct from
406	     * the hard duplicate rejected earlier by {@link #rejectDuplicateIdentity}: the owner is still
407	     * created, but flagged. When more than one existing owner matches, the earliest (lowest id) is
408	     * returned so the reference is deterministic. An owner with no postcode can never soft-match.
409	     *
410	     * @param owner the owner being created, with its telephone and postcode already normalized/validated
411	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
412	     */
413	    private Integer findPossibleDuplicateOf(Owner owner) {
414	        String postcode = owner.getPostcode();
415	        if (postcode == null) {
416	            return null;
417	        }
418	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
419	        String telephone = owner.getTelephone();
420	        return this.clinicService.findAllOwners().stream()
421	            .filter(this::isNotDeleted)
422	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
423	            .filter(existing -> postcode.equals(existing.getPostcode()))
424	            .filter(existing -> !java.util.Objects.equals(telephone, existing.getTelephone()))
425	            .map(Owner::getId)
426	            .filter(java.util.Objects::nonNull)
427	            .min(java.util.Comparator.naturalOrder())
428	            .orElse(null);
429	    }
430	
431	    /**
432	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
433	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
434	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
435	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
436	     * {@code "+61412345678"}. The E.164 value is stored and returned.
437	     * <p>
438	     * The national-number length (the digits after the country code) is additionally validated for
439	     * country codes with a fixed length: '+61' requires exactly 9 national digits and '+1' requires
440	     * exactly 10. Numbers of other country codes are only bound by the overall 8-to-15-digit limit.
441	     *
442	     * @param telephone the raw telephone as submitted
443	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
444	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
445	     *         or its national-number length is wrong for its country code
446	     */
447	    private String normalizeTelephone(String telephone) {
448	        String raw = telephone == null ? "" : telephone.trim();
449	        boolean hasCountryCode = raw.startsWith("+");
450	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
451	        if (hasCountryCode) {
452	            cleaned = cleaned.substring(1);
453	        }
454	        String digits;
455	        if (hasCountryCode) {
456	            digits = cleaned;
457	        } else {
458	            if (cleaned.startsWith("0")) {
459	                cleaned = cleaned.substring(1);
460	            }
461	            digits = "61" + cleaned;
462	        }
463	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
464	            throw new InvalidTelephoneException(telephone);
465	        }
466	        return "+" + digits;
467	    }
468	
469	    /**
470	     * Checks the national-number length of an E.164 digit string against its country code for the
471	     * country codes whose national number has a fixed length: '+61' requires 9 national digits and
472	     * '+1' requires 10. Any other country code passes, leaving it bound only by the overall length.
473	     *
474	     * @param digits the E.164 digits (the country code followed by the national number, without '+')
475	     * @return {@code true} if the national-number length is acceptable for the country code
476	     */
477	    private boolean hasValidNationalLength(String digits) {
478	        if (digits.startsWith("61")) {
479	            return digits.length() - 2 == 9;
480	        }
481	        if (digits.startsWith("1")) {
482	            return digits.length() - 1 == 10;
483	        }
484	        return true;
485	    }
486	
487	    /**
488	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
489	     * multi-character top-level label. Deliberately lenient about the exact character set while still
490	     * rejecting values that are clearly not addresses (e.g. missing '@').
491	     */
492	    private static final java.util.regex.Pattern EMAIL_PATTERN =
493	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
494	
495	    /**
496	     * Domains of known disposable/throwaway email providers. An owner whose email domain is on this
497	     * blocklist is rejected with a 400 Bad Request. Compared case-insensitively against the
498	     * lower-cased email domain.
499	     */
500	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
501	        "mailinator.com", "tempmail.com", "guerrillamail.com");
502	
503	    /**
504	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
505	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
506	     * lower-cased before being stored and returned.
507	     *
508	     * @param email the raw email as submitted, may be {@code null}
509	     * @return the lower-cased email, or {@code null} when none was supplied
510	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
511	     */
512	    private String normalizeEmail(String email) {
513	        if (email == null || email.isBlank()) {
514	            return null;
515	        }
516	        String trimmed = email.trim();
517	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
518	            throw new InvalidEmailException(email);
519	        }
520	        String normalized = trimmed.toLowerCase(java.util.Locale.ROOT);
521	        String domain = normalized.substring(normalized.indexOf('@') + 1);
522	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
523	            throw new DisposableEmailException(email);
524	        }
525	        return normalized;
526	    }
527	
528	    /**
529	     * Fixed region-to-postcode-range table: a region's postcode must fall within its inclusive range
530	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose region is not listed here (see
531	     * {@link Localities#region}) accepts any 4-digit postcode.
532	     */
533	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
534	        "NSW", new int[] {2000, 2099},
535	        "VIC", new int[] {3000, 3099},
536	        "QLD", new int[] {4000, 4099});
537	
538	    /**
539	     * Validates an owner's postcode on create. The postcode is optional: a {@code null} or blank value
540	     * is left as {@code null} (no postcode) and accepted. When present it must be exactly 4 digits and,
541	     * for a city whose region is in the fixed {@link #REGION_POSTCODE_RANGES range table}, must fall
542	     * within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no
543	     * known region accepts any 4-digit postcode. The value is stored and returned exactly as supplied.
544	     *
545	     * @param city the owner's city, used to derive the region whose range constrains the postcode
546	     * @param postcode the raw postcode as submitted, may be {@code null}
547	     * @return the postcode when supplied, or {@code null} when none was supplied
548	     * @throws InvalidPostcodeException (400 Bad Request) if a supplied postcode is not 4 digits or is
549	     *         out of range for the city's region
550	     */
551	    private String validatePostcode(String city, String postcode) {
552	        if (postcode == null || postcode.isBlank()) {
553	            return null;
554	        }
555	        if (!postcode.matches("[0-9]{4}")) {
556	            throw new InvalidPostcodeException(postcode);
557	        }
558	        int[] range = REGION_POSTCODE_RANGES.get(Localities.region(city));
559	        if (range != null) {
560	            int value = Integer.parseInt(postcode);
561	            if (value < range[0] || value > range[1]) {
562	                throw new InvalidPostcodeException(postcode);
563	            }
564	        }
565	        return postcode;
566	    }
567	
568	    /**
569	     * Common street-type abbreviations expanded to their full word during address normalization.
570	     */
571	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
572	        "ST", "STREET",
573	        "RD", "ROAD",
574	        "AVE", "AVENUE");
575	
576	    /**
577	     * Applies the owner's address on create from the structured fields when present, falling back to the
578	     * flat {@code address} for backward compatibility. An owner must supply an address in at least one
579	     * form: a non-blank {@code addressLine1} (the structured form, preferred) or a non-blank flat
580	     * {@code address}; when neither is present the create is rejected.
581	     * <p>
582	     * Whichever address fields are supplied are normalized (see {@link #normalizeAddress}). When the
583	     * structured form is used the normalized {@code addressLine1} and, when supplied, {@code addressLine2}
584	     * are stored on the owner and the composed {@code address} is the normalized {@code addressLine1} with
585	     * a single space and the normalized {@code addressLine2} appended when {@code addressLine2} is present.
586	     * When only the flat form is used the normalized flat value becomes the stored {@code address} and the
587	     * structured lines are left unset. The stored {@code address} is the value every later step reads.
588	     *
589	     * @param owner the owner being created
590	     * @param ownerFieldsDto the submitted owner fields carrying the raw address input
591	     * @throws InvalidAddressException (400 Bad Request) if no address is supplied in either form
592	     */
593	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
594	        String rawLine1 = ownerFieldsDto.getAddressLine1();
595	        String rawLine2 = ownerFieldsDto.getAddressLine2();
596	        String rawFlat = ownerFieldsDto.getAddress();
597	        boolean hasLine1 = rawLine1 != null && !rawLine1.isBlank();
598	        boolean hasFlat = rawFlat != null && !rawFlat.isBlank();
599	        if (!hasLine1 && !hasFlat) {
600	            throw new InvalidAddressException(rawLine1 != null ? rawLine1 : rawFlat);
601	        }
602	        if (hasLine1) {
603	            String line1 = normalizeAddress(rawLine1);
604	            String line2 = (rawLine2 != null && !rawLine2.isBlank()) ? normalizeAddress(rawLine2) : null;
605	            owner.setAddressLine1(line1);
606	            owner.setAddressLine2(line2);
607	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
608	        } else {
609	            owner.setAddressLine1(null);
610	            owner.setAddressLine2(null);
611	            owner.setAddress(normalizeAddress(rawFlat));
612	        }
613	    }
614	
615	    /**
616	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
617	     * whitespace collapse to a single space, the value is upper-cased and common street-type
618	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
619	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
620	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
621	     * for every address comparison (household duplicate detection and the shared household id).
622	     *
623	     * @param address the raw address as submitted
624	     * @return the normalized address
625	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
626	     */
627	    private String normalizeAddress(String address) {
628	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
629	        if (collapsed.isEmpty()) {
630	            throw new InvalidAddressException(address);
631	        }
632	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
633	        StringBuilder normalized = new StringBuilder(collapsed.length());
634	        for (int i = 0; i < tokens.length; i++) {
635	            if (i > 0) {
636	                normalized.append(' ');
637	            }
638	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
639	        }
640	        return normalized.toString();
641	    }
642	
643	    /**
644	     * Rejects creating an owner whose identity duplicates an existing owner's. All duplicate detection
645	     * is consolidated here onto the identity-bearing part of the derived {@code identityKey}: two
646	     * owners are duplicates when they share the same normalized telephone and the same normalized email
647	     * (a {@code null} email compared as an empty segment). Existing telephones are re-normalized to
648	     * E.164 and existing emails lower-cased before comparison, so equivalent values submitted in
649	     * different formats (e.g. national {@code "0412 345 678"} and international {@code "+61 412 345 678"})
650	     * still match.
651	     * <p>
652	     * The {@code householdId} is deliberately not part of this comparison: a household is a shared
653	     * grouping, so two members of the same household with different telephones have different
654	     * identities and are both allowed. Only owners with the same telephone and email collide.
655	     *
656	     * @param owner the owner being created, with its telephone and email already normalized
657	     * @throws DuplicateIdentityException (409 Conflict) if another owner has the same identity
658	     */
659	    private void rejectDuplicateIdentity(Owner owner) {
660	        String identity = personalIdentity(owner.getTelephone(), owner.getEmail());
661	        boolean duplicate = this.clinicService.findAllOwners().stream()
662	            .filter(this::isNotDeleted)
663	            .anyMatch(existing -> identity.equals(
664	                personalIdentity(toE164OrNull(existing.getTelephone()), existing.getEmail())));
665	        if (duplicate) {
666	            String householdId = Households.householdId(owner.getLastName(), owner.getPostcode());
667	            throw new DuplicateIdentityException(
668	                Households.identityKey(owner.getTelephone(), owner.getEmail(), householdId));
669	        }
670	    }
671	
672	    /**
673	     * Builds the identity-bearing prefix of the {@code identityKey} used for duplicate detection:
674	     * the normalized telephone and email joined with {@code '|'}, lower-casing the email (the form it
675	     * is stored in, see {@link #normalizeEmail}) so addresses differing only in letter case still match.
676	     */
677	    /**
678	     * Whether an existing owner is not soft-deleted. A soft-deleted owner (its {@code deleted} flag
679	     * set) is retained but ignored by the create endpoint's duplicate and identity checks, so a
680	     * normally-blocking duplicate is allowed when the only matching owner has been deleted.
681	     */
682	    private boolean isNotDeleted(Owner owner) {
683	        return !Boolean.TRUE.equals(owner.getDeleted());
684	    }
685	
686	    private String personalIdentity(String telephone, String email) {
687	        String normalizedEmail = email == null ? "" : email.toLowerCase(java.util.Locale.ROOT);
688	        return (telephone == null ? "" : telephone) + "|" + normalizedEmail;
689	    }
690	
691	    /**
692	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
693	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number, or
694	     * when its national-number length does not match its country code.
695	     */
696	    private String toE164OrNull(String telephone) {
697	        try {
698	            return normalizeTelephone(telephone);
699	        } catch (InvalidTelephoneException e) {
700	            return null;
701	        }
702	    }
703	
704	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
705	    @Override
706	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
707	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
708	        if (currentOwner == null) {
709	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
710	        }
711	        currentOwner.setAddress(ownerFieldsDto.getAddress());
712	        currentOwner.setCity(ownerFieldsDto.getCity());
713	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
714	        currentOwner.setLastName(ownerFieldsDto.getLastName());
715	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
716	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
717	        this.clinicService.saveOwner(currentOwner);
718	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
719	    }
720	
721	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
722	    @Transactional
723	    @Override
724	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
725	        Owner owner = this.clinicService.findOwnerById(ownerId);
726	        if (owner == null) {
727	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
728	        }
729	        this.clinicService.deleteOwner(owner);
730	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
731	    }
732	
733	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
734	    @Override
735	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
736	        Owner owner = this.clinicService.findOwnerById(ownerId);
737	        if (owner == null) {
738	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
739	        }
740	        HttpHeaders headers = new HttpHeaders();
741	        Pet pet = petMapper.toPet(petFieldsDto);
742	        owner.setId(ownerId);
743	        pet.setOwner(owner);
744	        pet.getType().setName(null);
745	        this.clinicService.savePet(pet);
746	        PetDto petDto = petMapper.toPetDto(pet);
747	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
748	            .buildAndExpand(pet.getId()).toUri());
749	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
750	    }
751	
752	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
753	    @Override
754	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
755	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
756	        if (currentOwner != null) {
757	            Pet currentPet = this.clinicService.findPetById(petId);
758	            if (currentPet != null) {
759	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
760	                currentPet.setName(petFieldsDto.getName());
761	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
762	                this.clinicService.savePet(currentPet);
763	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
764	            }
765	        }
766	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
767	    }
768	
769	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
770	    @Override
771	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
772	        HttpHeaders headers = new HttpHeaders();
773	        Visit visit = visitMapper.toVisit(visitFieldsDto);
774	        Pet pet = new Pet();
775	        pet.setId(petId);
776	        visit.setPet(pet);
777	        this.clinicService.saveVisit(visit);
778	        VisitDto visitDto = visitMapper.toVisitDto(visit);
779	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
780	            .buildAndExpand(visit.getId()).toUri());
781	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
782	    }
783	
784	
785	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
786	    @Override
787	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
788	        Owner owner = this.clinicService.findOwnerById(ownerId);
789	        if (owner != null) {
790	            Pet pet = owner.getPet(petId);
791	            if (pet != null) {
792	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
793	            }
794	        }
795	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
796	    }
797	}
